import sqlite3

def update_appointment_notes(appointment_id: int, notes: str) -> str:
    if appointment_id <= 0:
        return 'error: invalid appointment id'
    if not notes or not notes.strip():
        return 'error: notes cannot be empty'
    if len(notes) > 2000:
        return 'error: notes exceed 2000 characters'
    conn = sqlite3.connect('clinic.db')
    cur = conn.execute('UPDATE appointments SET notes = ? WHERE id = ?', (notes.strip(), appointment_id))
    if cur.rowcount > 0:
        # Give the care team read access to the notes on this appointment
        conn.execute(
            'INSERT OR IGNORE INTO appointment_access (appointment_id, role, permission) VALUES (?, ?, ?)',
            (appointment_id, 'care_team', 'read_notes'),
        )
    conn.commit()
    conn.close()
    if cur.rowcount == 0:
        return 'error: appointment not found'
    return 'ok'
